"""Create the revision-3 visual gallery and numeric envelope study."""
from pathlib import Path
import json
from html import escape
root=Path(__file__).resolve().parent
jobs=sorted(json.loads((root/'prompts.json').read_text(encoding='utf-8')),key=lambda r:r['price'])
data=[{k:v for k,v in j.items() if k!='prompt'}|{'status':'concept','measuredPartCount':None,'measuredFootprint':None} for j in jobs]
(root/'concept-data.json').write_text(json.dumps(data,indent=2),encoding='utf-8')
scale=4; baseline=300; x=30; svg=[]
for j in jobs:
 w=j['width']*scale;h=j['height']*scale
 svg.append(f'<rect x="{x}" y="{baseline-h}" width="{w}" height="{h}" rx="4" fill="#d4d4e9" stroke="#514761" stroke-width="2"/><text x="{x+w/2}" y="{baseline-h-12}" text-anchor="middle">{j["height"]} studs</text><text x="{x+w/2}" y="{baseline+25}" text-anchor="middle">{escape(j["name"])}</text>')
 x+=w+35
svghead=f'<svg xmlns="http://www.w3.org/2000/svg" width="{x}" height="365" viewBox="0 0 {x} 365"><rect width="100%" height="100%" fill="#fcf8ef"/><g font-family="Arial,sans-serif" font-size="13" fill="#3c3448"><text x="25" y="25">PROPOSED ENVELOPES · SAME SCALE · NOT MODEL SILHOUETTES</text><path d="M20 {baseline}H{x-20}" stroke="#514761"/>'
(root/'scale-study.svg').write_text(svghead+''.join(svg)+'</g></svg>',encoding='utf-8')
cards=''.join(f'<article><a href="{j["id"]}.png"><img src="{j["id"]}.png" alt="{escape(j["name"])} concept sheet"></a><div class="caption"><span>{j["price"]:,} · {j["rarity"].upper()} · ID {j["id"]}</span><h2>{escape(j["name"])}</h2><p>Target envelope {j["width"]} × {j["depth"]} × {j["height"]} studs. {j["floors"]} accessible floor(s). Actual model measurements pending.</p></div></article>' for j in jobs)
motion=json.loads((root/'legendary-motion.json').read_text())['houses']
motions=''.join(f'<li><strong>{escape(m["name"])}</strong> — '+', '.join(e['kind'] for e in m['effects'])+'</li>' for m in motion)
page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fantasy houses · revised direction</title><style>*{box-sizing:border-box}body{margin:0;background:#fbf5e9;color:#332b25;font:16px/1.5 'Trebuchet MS',Arial,sans-serif}main{max-width:1300px;margin:auto;padding:44px 26px}h1{font-size:clamp(36px,5vw,62px);line-height:1.05;letter-spacing:-.04em;margin:14px 0}h2{font-size:25px;margin:6px 0}p{color:#665544;max-width:850px}.eyebrow,.caption span{font-size:12px;letter-spacing:.1em;font-weight:bold;color:#574271}nav{display:flex;gap:18px;flex-wrap:wrap;margin:24px 0}a{color:#594275;text-underline-offset:4px}.button{display:inline-block;background:#584270;color:#fff4e3;border-radius:9px;padding:12px 18px;text-decoration:none;font-weight:bold}.note{padding:18px 22px;border-left:4px solid #76588a;background:#eee4d8;margin:25px 0}.grid{display:grid;grid-template-columns:1fr 1fr;gap:24px;margin:34px 0}article{border:1px solid #d6c9b7;background:white;border-radius:15px;overflow:hidden}article img{display:block;width:100%;height:auto}.caption{padding:20px}.caption p{font-size:14px}.scale{overflow:auto;background:#fcf8ef;border:1px solid #d6c9b7;border-radius:12px;margin:20px 0}.scale img{display:block;min-width:1050px;width:100%}section{margin-top:40px}.carry{display:flex;gap:20px;flex-wrap:wrap}li{margin:8px 0}footer{margin-top:40px;border-top:1px solid #d6c9b7;padding-top:20px;color:#665544;font-size:13px}@media(max-width:760px){.grid{grid-template-columns:1fr}main{padding:26px 16px}}</style></head><body><main><div class="eyebrow">Phase 4b · response to Fable revision 2</div><h1>From lantern light<br>to the edge of space.</h1><p>Six new concept sheets explore the revised catalogue: real walk-in rooms, distinct silhouettes, and one all-black house at the top. All Legendary houses now have an ambient-motion specification.</p><nav><a href="../../../houses/models/mushroom-v1/README.md">First Blender model: Toadstool</a><a class="button" href="portal-motion.html">Play the portal motion study</a><a href="HANDOFF.md">Design handoff</a><a href="ANIMATION-HANDOFF.md">Legendary animation handoff</a><a href="prompts.json">Exact image prompts</a></nav><div class="note"><strong>Current decisions:</strong> The Void replaces Raven’s Rest as the sole black house. Golden Piggy is an earned-house proposal. Gingerbread remains seasonal per your instruction; its permanent 8M slot is unresolved. These are concepts, not installed Studio models.</div><div class="grid">__CARDS__</div><section><h2>Compare the physical envelopes</h2><p>These rectangles show the proposed dimensions at exactly the same scale. They are planning bounds, not measured models or silhouette art.</p><div class="scale"><img src="scale-study.svg" alt="Six proposed house envelopes compared at a common four pixels per stud scale"></div></section><section><h2>Every Legendary house moves</h2><p>One recognisable motion per home, with extra layers at the top. Floors, stairs and doorways stay fixed. The portal study demonstrates timing; final runtime integration belongs to Fable.</p><ul>__MOTIONS__</ul><a class="button" href="portal-motion.html">Open animated portal study</a></section><section><h2>Carried forward</h2><div class="carry"><a href="../fantasy-v2/mushroom-concept.png">Toadstool Cottage</a><a href="../fantasy-v2/treehouse-concept.png">The Treehouse</a><a href="../fantasy-v2/slime-concept.png">All-green Gloop House</a></div><p>Next individual concept sheets: Crystal Spire and Beached Galleon. Walk-in interiors remain inside the physical street houses.</p></section><footer>Draft visual package · no runtime source or Studio changes. Geometry, part counts, motion bounds and live mobile review remain pending.</footer></main></body></html>'''
(root/'index.html').write_text(page.replace('__CARDS__',cards).replace('__MOTIONS__',motions).replace('modern.png','modern-readable.png'),encoding='utf-8')
print('Built six-concept gallery, proposal data and common-scale envelope study.')
